mapper.select:
SELECT specimen_exam_id, test_execution_id, specimen_type, specimen_status, collected_at, collected_by_id AS performer_id, TRIM(status) AS status FROM HOSPITAL.SPECIMEN_EXAM WHERE TRIM(status) = 'ACTIVE'
AND test_execution_id = #{searchValue}
AND TO_CHAR(collected_at, 'YYYY-MM-DD') = #{searchValue}
AND specimen_type = #{searchValue}
AND 1 = 0
ORDER BY collected_at DESC NULLS LAST, specimen_exam_id DESC
